INSERT INTO "audit_logs" ("id", "action", "table_name", "record_id", "old_data", "new_data", "user_id", "ip_address", "user_agent", "session_id", "timestamp") VALUES (4640, 'EVENT_REQUEST_CHANGE', 'event_requests', '828326', '{"id":828326,"firstName":"John","lastName":"Stern","email":"jstern@freshens.com","phone":"(678) 525-8066","organizationName":"Freshens","department":"","organizationCategory":null,"schoolClassification":null,"autoCategories":null,"categorizedAt":null,"categorizedBy":null,"desiredEventDate":"2025-12-17T00:00:00.000Z","backupDates":null,"scheduledEventDate":null,"isConfirmed":false,"addedToOfficialSheet":false,"message":"Freshens is an Atlanta based fresh casual restaurant company founded in 1985.  We license over 300 restaurants across the country, primarily on college campuses and airports.  Our corporate team (including out of town associates) will be in Atlanta the week of December 15th for end of year meetings.  We have reserved Wednesday, December 17th from 9am-12pm for community service.  We would like to prepare and deliver to the location that you specify, a minimum of 400 sandwiches.  Our corporate office has a full kitchen that is used for training and culinary development, so we have ample space to prepare sandwiches quickly and safely at our facility.  Our operations team has been certified in safe serv and can provide oversight to other team members to ensure that quality standards are met.  Please feel free to contact me (John Stern-CEO) at the number included.  I will be your primary contact along with Christina Jockwig, our VP of Marketing and Digital Content.  We look forward to serving the Atlanta Community in this very worthwhile endeavor.\n\nEvent Location: 1750 The Exchange Atlanta, GA 30339","previouslyHosted":"i_dont_know","status":"new","statusChangedAt":null,"assignedTo":null,"postponementReason":null,"tentativeNewDate":null,"postponementNotes":null,"followUpMethod":null,"updatedEmail":null,"followUpDate":null,"scheduled