INSERT INTO "audit_logs" ("id", "action", "table_name", "record_id", "old_data", "new_data", "user_id", "ip_address", "user_agent", "session_id", "timestamp") VALUES (4579, 'EVENT_REQUEST_CHANGE', 'event_requests', '804596', '{"id":804596,"firstName":"Kaley","lastName":"Quintanilla","email":"kaley.quintanilla4616@gcssk12.net","phone":"(770) 231-7942","organizationName":"Gainesville High School","department":"HoPe Chapter","organizationCategory":"school","schoolClassification":"public","autoCategories":null,"categorizedAt":null,"categorizedBy":null,"desiredEventDate":"2025-12-03T00:00:00.000Z","backupDates":[],"scheduledEventDate":"2025-12-03T00:00:00.000Z","isConfirmed":true,"addedToOfficialSheet":false,"message":"Hello the Sandwich Project,\n\n\nMy name is Kaley, and I''m the Vice President of Service at Gainesville High School Hope Chapter. HoPe is a student-led organization focused on leadership, community service, and supporting Hispanic youth as they grow and serve their communities.\n\nWe''re organizing a student-led service project for November or December, and we would love to partner with the Sandwich Project. Our chapter wants to help with sandwich making or any other tasks you may need support with. Our goal is to serve our community and make a positive impact through hands-on work.\n\nWould you be open to collaborating on this event or connecting for a quick conversation? You can reach me at Kaley.quintanilla4616@gcssk12.net.\n\nThank you for your time and consideration!\nWarm regards,\nKaley Quintanilla\nVP of Service at Gainesville High School HoPe Chapter\nBREATHE IT! LIVE IT! LOVE IT!\n\nEvent Location: 830 Century Pl, Gainesville, GA 30501","previouslyHosted":"i_dont_know","status":"scheduled","statusChangedAt":"2025-11-26T20:38:50.544Z","assignedTo":null,"postponementReason":null,"tentativeNewDate":null,"postponementNotes":null,"followUpMethod":null,"updatedEmail":null,"followUpDate":null,"scheduledCallDate":null,"contactedAt":null,"communicationMe