INSERT INTO "email_messages" ("id", "sender_id", "sender_name", "sender_email", "recipient_id", "recipient_name", "recipient_email", "subject", "content", "is_read", "is_starred", "is_archived", "is_trashed", "is_draft", "parent_message_id", "context_type", "context_id", "context_title", "attachments", "include_scheduling_link", "request_phone_call", "read_at", "created_at", "updated_at") VALUES (55, 'user_1751071509329_mrkw2z95z', 'Katie (Main) Long', 'katielong2316@gmail.com', 'user_1753474181789_yxnaf1pai', 'Nancy Miller', 'atlantamillers@comcast.net', 'Thank you!', 'Thank you for trying out the app and putting in your numbers for this week! I really appreciate it! If you had any problems or have any feedback on what we can make work better for you, please let me know. I did add a walkthrough feature for entering your sandwich #''s that may more may not be easier. Feel free to try it next week or look at it before then and again, just let me know any thoughts you have!
INSERT INTO "email_messages" ("id", "sender_id", "sender_name", "sender_email", "recipient_id", "recipient_name", "recipient_email", "subject", "content", "is_read", "is_starred", "is_archived", "is_trashed", "is_draft", "parent_message_id", "context_type", "context_id", "context_title", "attachments", "include_scheduling_link", "request_phone_call", "read_at", "created_at", "updated_at") VALUES (57, 'user_1751071509329_mrkw2z95z', 'Katie (Main) Long', 'katielong2316@gmail.com', 'user_1753473977467_ld546am0n', 'Jordan Glick', 'jordanglick@gmail.com', 'Thank you!', 'Thanks for putting your numbers in the app for last week! Was it easy for you? Anything I can tweak to make it more straightforward- the goal is for this to take as little effort as possible, and definitely for it to be simpler than the google form and the headaches it caused!', FALSE, FALSE, FALSE, FALSE, FALSE, NULL, NULL, NULL, NULL, '{}', FALSE, FALSE, NULL, '2025-08-10T02:20:59.717Z', '2025-08-10T02:20:59.717Z') ON CONFLICT DO NOTHING;
