Z', NULL, NULL, NULL, '1201 W Peachtree, Atlanta, GA 30309 - Building One Atlantic Center', 500, TRUE, NULL, NULL, 'user_1757084925377_awxbihnn4', '2025-10-28T17:25:50.150Z', NULL, NULL, NULL, NULL, TRUE, '2025-10-30T12:00:00.000Z', 'sent', 'user_1757084925377_awxbihnn4', '14:00', '15:00', NULL, NULL, NULL, 'Parking across street by Rising Roll. Security will let you into bank of elevators. Come to 20th floor and meet with Equifax Security Person where you''ll meet with an Equifax Rep.', 'Parking across street by Rising Roll. Security will let you into bank of elevators. Come to 20th floor and meet with Equifax Security Person where you''ll meet with an Equifax Rep. - Kim + Madeline Hill and Caroline Sizer. Take to Jordan or Henry?', NULL, NULL, NULL, NULL, 1, 1, 2, NULL, NULL, NULL, NULL, FALSE, '{"user_1756855307041_by1nnrlif"}', NULL, '{"volunteer-146"}', '{}', FALSE, NULL, NULL, NULL, FALSE, NULL, FALSE, NULL, NULL, FALSE, NULL, FALSE, NULL, NULL, NULL, 25, NULL, NULL, NULL, 250, '[{"type":"Deli","quantity":250}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, '', 0, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, '56', 'auto-amFuZS5sbG95ZEBlcXVp', '2025-10-28T16:29:09.144Z', NULL, '{"user_1756855307041_by1nnrlif":{"name":"Kim Ross","assignedAt":"2025-11-05T14:33:00.912Z","assignedBy":"user_1756855040337_5ix2krxc7"}}'::jsonb, '2025-10-28T12:27:06.000Z', '2025-11-18T18:24:58.002Z', 'google_sheets_sync', 25, 'large_corp', NULL, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, NULL, '[]'::jsonb, '33.7871136', '-84.38726319999999', FALSE, NULL, NULL, '[]'::jsonb, 1, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[]'::jsonb, NULL) ON CONFLICT DO NOTHING;
