INSERT INTO "impact_reports" ("id", "report_type", "report_period", "start_date", "end_date", "title", "executive_summary", "content", "metrics", "highlights", "trends", "generated_at", "generated_by", "ai_model", "generation_prompt", "regeneration_count", "status", "published_at", "published_by", "pdf_url", "pdf_generated_at", "tags", "notes", "created_at", "updated_at") VALUES (1, 'monthly', '2025-11', '2025-11-01T00:00:00.000Z', '2025-12-01T00:00:00.000Z', 'Spreading Hope: November 2025 Impact Report', 'In November 2025, The Sandwich Project achieved remarkable milestones in our mission to combat food insecurity. Over the course of 46 events, we distributed an impressive 32,278 sandwiches to people in need, partnering with 79 organizations across various sectors. From schools and corporations to faith-based groups and community clubs, every partnership strengthened our capacity to serve. With the support of 40 dedicated volunteers, all activities were completed at zero cost, demonstrating the power of community collaboration and efficient resource management. 
